#!/usr/bin/env bash
# 039 -- testes da futura V1.0.277 (link em preparo + Nobeds sai sem estrago) numa copia do codigo instalado (1.0.276) em /tmp. Nada instalado.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v277.XXXX)
echo "" | base64 -d > $T/p.patch
echo "6656a1531ed0da4b21cba0a5f9b6dee9c1e29911b4286008cc9a880ccad65504  $T/p.patch" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
mkdir -p $T/repo && (cd /opt/PMS-Banana-AI && tar cf - --exclude=.venv --exclude=__pycache__ --exclude='*.pyc' --exclude=node_modules SISTEMA 2>/dev/null) | (cd $T/repo && tar xf - 2>/dev/null)
cd $T/repo && echo "copia: $(grep -oP 'VERSAO = "\K[^"]+' SISTEMA/api/app/versao.py)" && patch -p1 -s --no-backup-if-mismatch < $T/p.patch && echo "pacote 277 aplicado"
cd $T/repo/SISTEMA
P() { env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 600 /opt/PMS-Banana-AI/SISTEMA/.venv/bin/pytest -o addopts="-p no:cacheprovider" "$@" 2>&1; }
echo "== testes novos"; P -q api/app/channel/tests/test_v1277_nobeds_fim_e_link_em_preparo.py | grep -vE '^\s*$' | tail -50 | cut -c1-240
echo "== suite inteira"; P -q --maxfail=60 api | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed|error)' | tail -40 | cut -c1-200
rm -rf $T
